"""Tiny JSON Schema -> TypeScript generator for the subset pydantic emits.

Why not json-schema-to-typescript: zero extra dependencies, and it fails loudly on any schema
feature it does not understand, instead of silently emitting `any`.
"""

import json
import re
from typing import Any

IDENT = re.compile(r"^[A-Za-z_$][A-Za-z0-9_$]*$")
HEADER = (
    "// GENERATED by tools/export_contracts.py from the Python contracts. DO NOT EDIT.\n"
    "// Source of truth: services/api/corvo_api/contracts/\n\n"
)


def ref_name(ref: str) -> str:
    prefix = "#/$defs/"
    if not ref.startswith(prefix):
        raise ValueError(f"unsupported $ref {ref}")
    return ref[len(prefix):]


def ts_type(s: dict[str, Any], indent: int = 0) -> str:
    if "$ref" in s:
        return ref_name(s["$ref"])
    if "const" in s:
        return json.dumps(s["const"])
    if "enum" in s:
        return " | ".join(json.dumps(v) for v in s["enum"])
    if "anyOf" in s:
        return " | ".join(ts_type(x, indent) for x in s["anyOf"])
    if "allOf" in s and len(s["allOf"]) == 1:
        return ts_type(s["allOf"][0], indent)
    t = s.get("type")
    if t in ("string",):
        return "string"
    if t in ("integer", "number"):
        return "number"
    if t == "boolean":
        return "boolean"
    if t == "null":
        return "null"
    if t == "array":
        if "prefixItems" in s:
            return "[" + ", ".join(ts_type(x, indent) for x in s["prefixItems"]) + "]"
        inner = ts_type(s["items"], indent)
        return f"({inner})[]" if "|" in inner else f"{inner}[]"
    if t == "object":
        return ts_object(s, indent)
    raise ValueError(f"unsupported schema node: {json.dumps(s)[:200]}")


def ts_object(s: dict[str, Any], indent: int) -> str:
    props = s.get("properties")
    if props is None:
        ap = s.get("additionalProperties")
        if isinstance(ap, dict):
            return f"Record<string, {ts_type(ap, indent)}>"
        return "Record<string, unknown>"
    required = set(s.get("required", []))
    pad = "  " * (indent + 1)
    lines = []
    for name, sub in props.items():
        key = name if IDENT.match(name) else json.dumps(name)
        opt = "" if name in required else "?"
        doc = f"{pad}/** {sub['description']} */\n" if sub.get("description") else ""
        lines.append(f"{doc}{pad}{key}{opt}: {ts_type(sub, indent + 1)};")
    return "{\n" + "\n".join(lines) + "\n" + "  " * indent + "}"


def generate(schema: dict[str, Any]) -> str:
    out = [HEADER]
    for name in sorted(schema["$defs"]):
        d = schema["$defs"][name]
        if d.get("type") == "object" and "properties" in d:
            out.append(f"export interface {name} {ts_object(d, 0)}\n")
        else:
            out.append(f"export type {name} = {ts_type(d)};\n")
    return "\n".join(out)
